//! Embedded vector-drawn icon set for the Net Flow Adaptive Card.
//!
//! Every glyph is a pre-rasterised 36x36 RGBA PNG (rendered at 256x256 and
//! Lanczos-downsampled) encoded as a data URI, so cards never depend on
//! emoji fonts — which render inconsistently and at the wrong optical weight
//! inside the Windows Widget Board host.
//!
//! Generated by `scripts/gen_icons.py`; do not edit by hand.

pub const MEDIUM_WIFI: &str = "data:image/png;base64,";

pub const MEDIUM_ETHERNET: &str = "data:image/png;base64,";

pub const MEDIUM_CELLULAR: &str = "data:image/png;base64,";

pub const MEDIUM_GLOBE: &str = "data:image/png;base64,";

pub const MEDIUM_LOOPBACK: &str = "data:image/png;base64,";

pub const ARROW_DOWN: &str = "data:image/png;base64,";

pub const ARROW_UP: &str = "data:image/png;base64,";

pub const PULSE: &str = "data:image/png;base64,";

pub const CHEVRON_DOWN: &str = "data:image/png;base64,";

pub const CHEVRON_UP: &str = "data:image/png;base64,";

pub const CHEVRON_LEFT: &str = "data:image/png;base64,";

pub const CHEVRON_RIGHT: &str = "data:image/png;base64,";

pub const APP_CODE: &str = "data:image/png;base64,";

pub const APP_TERMINAL: &str = "data:image/png;base64,";

pub const APP_CHAT: &str = "data:image/png;base64,";

pub const APP_MUSIC: &str = "data:image/png;base64,";

pub const APP_VIDEO: &str = "data:image/png;base64,";

pub const APP_GAME: &str = "data:image/png;base64,";

pub const APP_SHIELD: &str = "data:image/png;base64,";

pub const APP_CLOUD: &str = "data:image/png;base64,";

pub const APP_MAIL: &str = "data:image/png;base64,";

pub const APP_DOC: &str = "data:image/png;base64,";
pub const APP_SYSTEM: &str = "data:image/png;base64,";

pub const SETTINGS: &str = "data:image/png;base64,";

pub const APP_CHART: &str = "data:image/png;base64,";

pub const APP_FOLDER: &str = "data:image/png;base64,";

pub const APP_SPARKLE: &str = "data:image/png;base64,";

pub const APP_GENERIC: &str = "data:image/png;base64,";

/// Map a legacy emoji hint (produced by `process::map_process_to_app`) onto a
/// vector glyph, so app rows never fall back to emoji rendering.
pub fn app_glyph_for_emoji(emoji: &str) -> &'static str {
    match emoji {
        "💻" | "🦀" | "🐍" | "🐳" => APP_CODE,
        "✨" => APP_SPARKLE,
        "💬" => APP_CHAT,
        "🎵" => APP_MUSIC,
        "🎬" | "🎥" | "📹" => APP_VIDEO,
        "🎮" => APP_GAME,
        "🔒" => APP_SHIELD,
        "☁️" | "☁" => APP_CLOUD,
        "✉️" | "✉" => APP_MAIL,
        "📝" => APP_DOC,
        "⚙️" | "⚙" => APP_SYSTEM,
        "📊" => APP_CHART,
        "📁" => APP_FOLDER,
        "🖥" | "🖥️" => APP_TERMINAL,
        _ => MEDIUM_GLOBE,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_glyph_is_a_png_data_uri() {
        use base64::Engine;
        for uri in [
            MEDIUM_WIFI,
            MEDIUM_ETHERNET,
            MEDIUM_CELLULAR,
            MEDIUM_GLOBE,
            MEDIUM_LOOPBACK,
            ARROW_DOWN,
            ARROW_UP,
            PULSE,
            CHEVRON_DOWN,
            CHEVRON_UP,
            CHEVRON_LEFT,
            CHEVRON_RIGHT,
            APP_CODE,
            APP_TERMINAL,
            APP_CHAT,
            APP_MUSIC,
            APP_VIDEO,
            APP_GAME,
            APP_SHIELD,
            APP_CLOUD,
            APP_MAIL,
            APP_DOC,
            APP_SYSTEM,
            SETTINGS,
            APP_CHART,
            APP_FOLDER,
            APP_SPARKLE,
            APP_GENERIC,
        ] {
            assert!(uri.starts_with("data:image/png;base64,"));
            let b64 = uri.strip_prefix("data:image/png;base64,").unwrap();
            let decoded = base64::engine::general_purpose::STANDARD
                .decode(b64)
                .expect("glyph must be valid base64");
            assert!(decoded.len() > 64, "glyph payload looks truncated");
            assert_eq!(
                &decoded[..8],
                &[137, 80, 78, 71, 13, 10, 26, 10],
                "glyph must have valid PNG magic header"
            );
            let img = image::load_from_memory(&decoded)
                .expect("glyph must be completely valid readable PNG");
            assert_eq!(img.width(), 36);
            assert_eq!(img.height(), 36);
        }
    }

    #[test]
    fn emoji_hints_resolve_to_glyphs() {
        assert_eq!(app_glyph_for_emoji("💬"), APP_CHAT);
        assert_eq!(app_glyph_for_emoji("🦀"), APP_CODE);
        assert_eq!(app_glyph_for_emoji("⚙️"), APP_SYSTEM);
        // Unknown hints degrade to the neutral globe rather than raw emoji.
        assert_eq!(app_glyph_for_emoji("🧅"), MEDIUM_GLOBE);
    }
}
